-- =============================================================
-- V63：全国省市区三级行政区划数据（modood/Administrative-divisions-of-China）
-- 数据源：pca-code.json（国标行政区划代码，code 统一国标口径）
-- 说明：region 单表三级（level 1省/2市/3区），parent_id 表达层级；
--       直辖市（京津沪渝）省下直接挂区，跳过「市辖区」伪层级；
--       港澳台不在本数据范围。
-- 幂等：按 code 判重，已存在则跳过（保留既有 id 与经纬度）。
-- =============================================================

-- 国标行政区划 code 全局唯一，加唯一键使下方 INSERT ... ON DUPLICATE KEY UPDATE 幂等生效。
SET @idx := (SELECT COUNT(*) FROM information_schema.STATISTICS
             WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'region' AND INDEX_NAME = 'uk_region_code');
SET @sql := IF(@idx = 0,
  'ALTER TABLE region ADD UNIQUE KEY uk_region_code (code)',
  'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
ON DUPLICATE KEY UPDATE name = VALUES(name);

-- =============================================================
-- 门店城市强关联：store_profile 新增 city_id（关联 region.id）
-- =============================================================
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'store_profile'
             AND COLUMN_NAME = 'city_id');
SET @s := IF(@c = 0,
  'ALTER TABLE store_profile ADD COLUMN city_id BIGINT UNSIGNED NULL COMMENT ''城市ID（关联 region.id，level=2）'' AFTER city',
  'SELECT 1');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @idx := (SELECT COUNT(*) FROM information_schema.STATISTICS
             WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'store_profile' AND INDEX_NAME = 'idx_store_profile_city');
SET @s := IF(@idx = 0,
  'ALTER TABLE store_profile ADD INDEX idx_store_profile_city (city_id)',
  'SELECT 1');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- 回填 city_id：按 city 名精确匹配 region(level=2)，历史 seed 的 city 存完整城市名（如「长沙市」）
UPDATE store_profile sp
JOIN region r ON r.name = sp.city AND r.level = 2 AND r.deleted = 0
SET sp.city_id = r.id
WHERE sp.city_id IS NULL AND sp.deleted = 0;
